import fs from 'node:fs';import{pathToFileURL}from'node:url';const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError,LIVE_REGISTRY_OPERATIONS}=await import(new URL('live.js',base));
