for(const key of['playing','arrangementRecord','sessionRecord'])for(const value of[true,false,null])await run(valid,{transport:{[key]:value}});for(const key of['playingTargets','firedTargets'])await run(valid,{[key]:[{trackRef:'track:one',clipSlotRef:'slot:one',sceneRef:'scene:one',sceneIndex:0,clipRef:'clip:one'}]});
const capture={captureId:'capture:fixture',sourceSlotRef:'clip-slot:source',destinationSlotRef:'clip-slot:dest',state:'cleaned',active:false,playbackStopped:true};const record={state:'uncertain',captureId:capture.captureId,sourceSlotRef:capture.sourceSlotRef,destinationSlotRef:capture.destinationSlotRef};for(const value of[capture,{...capture,clip:{}},{...capture,clip:null},{...capture,residual:[]},{...capture,residual:['one']},...Object.keys(capture).map(key=>({...capture,[key]:null})),null])await run(valid,{owner:'audioCaptureTransactions',record,capture:value});
