for(const tool of ['message','python','undo-begin','undo-end','browser-preview','browser-stop','observe-poll','readonly'])for(const fault of ['none','error','refusal','nothing']){const sim=new DeterministicLiveSimulator(),calls=[];const status={...sim.status(),operations:LIVE_REGISTRY_OPERATIONS};const adapter={status:()=>status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>sim.invoke(i),subscribe:l=>sim.subscribe(l),snapshotAsync:(c,r)=>sim.snapshotAsync(c,r),discoverAsync:(r,c)=>sim.discoverAsync(r,c),getAsync:(r,c)=>sim.getAsync(r,c),refreshStatusAsync:async()=>status,invokeAsync:async i=>{calls.push(i.operation);if(fault==='error')throw Error('injected failure');if(fault==='refusal')throw new LiveMutationNotDispatchedError('not dispatched');if(fault==='nothing')throw Error('Nothing changed in Live: refused');switch(i.operation){case'application.message':return{shown:true};case'undo.step.begin':return{open:true,stepId:'step-fixture',expiresAt:9999999999999};case'undo.step.end':return{open:false};case'browser.inspect':return{id:'item',objectIdentity:'browser-object',name:'Sample'};case'browser.preview.start':return{previewId:'p'.repeat(32)};case'browser.preview.stop':return{stopped:true};default:return{};}}};const host=new McpHost(adapter),record={id:'fixture',state:'applied',epoch:1,expiresAt:9999999999999};host.transactions.set('fixture',record);host.liveUndoDispatchAsync=async()=>{switch(tool){case'message':await host.liveMessageAsync(2,{text:'Message'});break;case'python':await host.liveRunPythonAsync(2,{code:'1'});break;case'undo-begin':await host.liveUndoStepBeginAsync(2,{});break;case'undo-end':await host.liveUndoStepEndAsync(2,{});break;case'browser-preview':await host.liveBrowserPreviewAsync(2,{itemId:'item'});break;case'browser-stop':await host.liveBrowserPreviewStopAsync(2,{previewId:'p'.repeat(32)});break;case'observe-poll':await host.liveObservePollAsync(2,{subscriptionId:'one'});break;case'readonly':await host.liveSongStateAsync(2,{});break;}record.state='uncertain';return host.adapterToolError(1,Error('an undo read failed'),'Check the Set.');};const result=await host.liveUndoAsync(1,{transactionId:'fixture',confirmation:'undo',idempotencyKey:'undo-key'});watches.push({tool,fault,result:clean(result),state:record.state,calls});}
